(() => { const p = document.querySelector('.panel.calendar').getBoundingClientRect();
 const cells = [...document.querySelectorAll('.calendar__grid > *')].map(c => { const r = c.getBoundingClientRect(); return { x: r.x - p.x, y: r.y - p.y, w: r.width, h: r.height, entry: c.classList.contains('has-entry'), blank: c.classList.contains('calendar__blank'), day: (c.textContent || '').trim().match(/^\d+/)?.[0] || '' }; });
 let pre = document.getElementById('__dump'); if (!pre) { pre = document.createElement('pre'); pre.id = '__dump'; pre.style.cssText = 'position:fixed;left:0;top:0;width:1px;height:1px;overflow:hidden;opacity:0;white-space:pre;'; document.body.appendChild(pre); }
 pre.textContent = JSON.stringify({ month: document.querySelector('.calendar__head')?.textContent?.trim().slice(0, 20), cells }); })()
